  "name": "run_command",
  "input": {
    "command": "echo '=== Trash ===' && du -sh ~/.Trash 2>/dev/null; echo '=== User Caches ===' && du -sh ~/Library/Caches 2>/dev/null; echo '=== User Logs ===' && du -sh ~/Library/Logs 2>/dev/null; echo '=== Downloads ===' && du -sh ~/Downloads 2>/dev/null"
  }
}

